/// Samples a residual covers: half before the step and half after.
pub const BLEP_TAPS: usize = 16;
/// Fractional positions of a step between two samples, as a shift; the
/// tables have one row more, so that every position has a row on each side.
pub const BLEP_PHASES_SHIFT: u32 = 6;
